import struct
import zlib


def rec(seq, kind, tx, payload=b"", crc=None):
    header = struct.pack("<IIBI", len(payload), seq, kind, tx)
    body = header + payload
    c = zlib.crc32(body) & 0xFFFFFFFF if crc is None else crc
    return body + struct.pack("<I", c)


def begin(seq, tx):
    return rec(seq, 1, tx)


def patch(seq, tx, pi, off, data):
    return rec(seq, 2, tx, struct.pack("<HHH", pi, off, len(data)) + data)


def commit(seq, tx, patches, count=None, digest=None):
    cat = b"".join(patches)
    d = zlib.crc32(cat) & 0xFFFFFFFF
    n = len(patches)
    body = struct.pack(
